import sys

def can_construct_brute(ransom, magazine):
    pool = list(magazine)
    for ch in ransom:
        if ch in pool:
            pool.remove(ch)
        else:
            return False
    return True

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if can_construct_brute(data[0], data[1]) else 'false')

import sys

def can_construct_opt(ransom, magazine):
    cnt = [0] * 26
    for ch in magazine:
        cnt[ord(ch) - ord('a')] += 1
    for ch in ransom:
        idx = ord(ch) - ord('a')
        cnt[idx] -= 1
        if cnt[idx] < 0:
            return False
    return True

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if can_construct_opt(data[0], data[1]) else 'false')

import sys
from collections import Counter

def can_construct_best(ransom, magazine):
    if len(ransom) > len(magazine):
        return False
    cnt = Counter(magazine)
    for ch in ransom:
        cnt[ch] -= 1
        if cnt[ch] < 0:
            return False
    return True

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if can_construct_best(data[0], data[1]) else 'false')
